// src/components/CountdownTimer.js
import React, { useState, useEffect } from 'react';

const CountdownTimer = ({ language }) => {
  const [timeLeft, setTimeLeft] = useState({});
  const [electionData, setElectionData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Remove Gemini API call and use static data
  useEffect(() => {
    const fetchElectionData = async () => {
      try {
        setLoading(true);
        
        // Use static election data instead of Gemini API
        const staticElectionData = {
          electionDate: '2024-04-19',
          electionType: 'Lok Sabha Elections 2024',
          phases: 7,
          resultDate: '2024-06-04'
        };

        setElectionData(staticElectionData);
        setLoading(false);
        
      } catch (error) {
        console.error('Error fetching election data:', error);
        setError(language === 'hindi' 
          ? 'चुनाव डेटा लोड नहीं हो सका' 
          : 'Could not load election data'
        );
        setLoading(false);
      }
    };

    fetchElectionData();
  }, [language]);

  // Countdown calculation
  useEffect(() => {
    if (!electionData) return;

    const calculateTimeLeft = () => {
      const electionDate = new Date(electionData.electionDate);
      const now = new Date();
      const difference = electionDate - now;

      if (difference > 0) {
        setTimeLeft({
          days: Math.floor(difference / (1000 * 60 * 60 * 24)),
          hours: Math.floor((difference / (1000 * 60 * 60)) % 24),
          minutes: Math.floor((difference / 1000 / 60) % 60),
          seconds: Math.floor((difference / 1000) % 60)
        });
      } else {
        setTimeLeft({ days: 0, hours: 0, minutes: 0, seconds: 0 });
      }
    };

    calculateTimeLeft();
    const timer = setInterval(calculateTimeLeft, 1000);

    return () => clearInterval(timer);
  }, [electionData]);

  const translations = {
    hindi: {
      title: "लोकसभा चुनाव 2024",
      days: "दिन",
      hours: "घंटे",
      minutes: "मिनट",
      seconds: "सेकंड",
      electionStarts: "चुनाव शुरू",
      phases: "चरण",
      resultsOn: "नतीजे"
    },
    english: {
      title: "Lok Sabha Elections 2024",
      days: "Days",
      hours: "Hours",
      minutes: "Minutes",
      seconds: "Seconds",
      electionStarts: "Election Starts",
      phases: "Phases",
      resultsOn: "Results On"
    }
  };

  const t = translations[language];

  if (loading) {
    return (
      <div className="countdown-timer">
        <div className="loading">Loading election data...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="countdown-timer">
        <div className="error">{error}</div>
      </div>
    );
  }

  return (
    <div className="countdown-timer">
      <div className="countdown-header">
        <h2>{t.title}</h2>
        <div className="election-info">
          <span className="election-badge">{electionData.electionType}</span>
          <span className="phase-badge">{t.phases}: {electionData.phases}</span>
        </div>
      </div>

      <div className="countdown-grid">
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.days || 0}</div>
          <div className="countdown-label">{t.days}</div>
        </div>
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.hours || 0}</div>
          <div className="countdown-label">{t.hours}</div>
        </div>
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.minutes || 0}</div>
          <div className="countdown-label">{t.minutes}</div>
        </div>
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.seconds || 0}</div>
          <div className="countdown-label">{t.seconds}</div>
        </div>
      </div>

      <div className="election-dates">
        <div className="date-info">
          <span className="date-label">{t.electionStarts}:</span>
          <span className="date-value">{new Date(electionData.electionDate).toLocaleDateString()}</span>
        </div>
        <div className="date-info">
          <span className="date-label">{t.resultsOn}:</span>
          <span className="date-value">{new Date(electionData.resultDate).toLocaleDateString()}</span>
        </div>
      </div>
    </div>
  );
};

export default CountdownTimer;
